import { PromptBar } from "solen-design/react";

<PromptBar
  placeholder="Ask anything"
  width={400}
  radius={16}
  maxRows={5}
  morphDuration={240}
  squash={0.12}
  tilt={8}
  defaultEffort="Max"
  onSend={(text, meta) => console.log(text, meta)}
  onStop={() => console.log("stop")}
